// Marcatori ASCII per stato todo (niente emoji, regola A del CLAUDE.md).
const STATUS_MARKER: Record<string, string> = {
  completed: "[x]",
  in_progress: "[~]",
  blocked: "[!]",
  skipped: "[-]",
  pending: "[ ]",
};

interface PlanTodo {
  id?: string;
  seq?: number;
  content?: string;
  status?: string;
  priority?: string;
}

/**
 * Checklist live dei todo di un piano agente.
 *
 * Stato iniziale dai todo nel payload del meta-step `plan`; aggiornamenti in
 * tempo reale via eventi `TodoUpdated` filtrati sul `run_id` del piano
 * (payload.plan_id, che coincide con il run_id del run agente).
 */
function PlanChecklist({ runId, todos }: { runId: string | null; todos: PlanTodo[] }) {
  // overrides[todo_id] = status piu' recente ricevuto via SSE.
  const [overrides, setOverrides] = useState<Record<string, string>>({});

  useEffect(() => {
    if (!runId) return;
    const unsubscribe = subscribeAll((env) => {
      const ev = env.payload;
      if (ev.kind === "TodoUpdated" && ev.run_id === runId) {
        setOverrides((prev) =>
          prev[ev.todo_id] === ev.status ? prev : { ...prev, [ev.todo_id]: ev.status },
        );
      }
    });
    return unsubscribe;
  }, [runId]);

  if (!todos.length) return <em className="text-xs opacity-70">Nessun todo</em>;

  return (
    <ol className="list-none pl-0 space-y-0.5 text-xs">
      {todos.map((t, i) => {
        const status = (t.id ? overrides[t.id] : undefined) ?? t.status ?? "pending";
        const marker = STATUS_MARKER[status] ?? STATUS_MARKER.pending;
        return (
          <li
            key={t.id ?? i}
            className="leading-snug flex items-start gap-1.5"
            style={{ minWidth: 0 }}
          >
            <span className="font-mono opacity-70" style={{ flexShrink: 0 }}>{marker}</span>
            <span style={{ minWidth: 0, flex: 1 }}>
              {t.content ?? "—"}
              {t.priority && t.priority !== "normal" ? (
                <span className="opacity-60"> ({t.priority})</span>
              ) : null}
            </span>
          </li>
        );
      })}
    </ol>
  );
}

function renderPayload(kind: string, payload: Record<string, unknown>) {
  if (kind === "plan") {
    const todos = (payload.todos ?? []) as PlanTodo[];
    // Il run id del piano e' in payload.plan_id (coincide col run_id agente).
    const runId =
      typeof payload.plan_id === "string" ? payload.plan_id : null;
    return <PlanChecklist runId={runId} todos={todos} />;
  }

